"@H1|۱۸. رسانه و روایت عمومی: چگونه یک بانک، خبر می‌شود",
"@P|در بازهٔ ۱۴۰۳ تا ۱۴۰۵، ایران زمین در رسانه‌های ایران، «حضور مستمر» داشت. اما این «حضور»، «تبلیغ» نبود؛ «خبر بحران» بود. و «تیترها»، یک «روایت» ساختند: «بانکی که زیانش از سرمایه‌اش گذشت». و «بانک»، در این «روایت»، «سوژه» بود، نه «منبع».",
"@P|سه «قاب» اصلی در تیترها دیده می‌شود. قاب اول: «عدد». «زیان ۲۵ هزار میلیاردی»، «زیان انباشته ۷۹ هزار میلیاردی»، «کفایت منفی ۷۰ درصد» (S05، S06، S22). قاب دوم: «توقیف». «۷۵ همت اموال»، «اضافه‌برداشت ۱۱۰ همت» (S14). قاب سوم: «سرنوشت». «ادغام یا انحلال؟»، «آیا بانک ورشکسته است؟» (S10، S16).",
"@P|این سه قاب، «مکمل» هستند. «عدد»، «بحران» را «اثبات» می‌کند. «توقیف»، «مداخله» را «نشان» می‌دهد. «سرنوشت»، «ترس» را «زنده» می‌کند. و «ترس»، «کلیک» می‌آورد. و «کلیک»، «خبر بیشتر» می‌سازد. و «خبر بیشتر»، «ترس بیشتر». و این «حلقه»، «رسانه» را «شریک بحران» می‌کند؛ نه از «بدخواهی»، بلکه از «اقتصاد توجه».",
"@T|T19",
"@P|جدول بالا، «قاب»ها را نشان می‌دهد. ستون «واکنش بانک»، خالی است. و این «خالی»، «الگو» است. اما «نکتهٔ مهم» این است: «رسانه» «دشمن» نیست. «رسانه»، «آینه» است. اگر «بانک» «حرف» نداشته باشد، «آینه» «سکوت» را «بحران» نشان می‌دهد. و «بحران»، «خبر» است.",
"@P|دربارهٔ «لحن»، سه «سطح» وجود دارد. سطح اول: «خبری». «زیان اعلام شد». سطح دوم: «تحلیلی». «زیان به‌دلیل اسپرد منفی است». سطح سوم: «قضاوتی». «سرنوشت محتوم، ورشکستگی است» (S16). و «سطح سوم»، «مرز» «تحلیل» و «فتوا» است. و در این پرونده، «سطح سوم» «رایج» شد.",
"@P|«سطح سوم» یک «اثر» دارد: «بستن راه». وقتی رسانه می‌گوید «سرنوشت محتوم»، «مخاطب» «راه» را «بسته» می‌بیند. و «راه بسته»، «هجوم» می‌سازد. و «هجوم»، «پیش‌بینی» را «خودمحقق» می‌کند. و این، «مسئولیت رسانه» است، نه فقط «بانک».",
"@P|دربارهٔ «منبع»، یک «الگو» وجود دارد: بیشتر «خبرها» از «گزارش‌های رسمی» و «مصاحبهٔ مقامات» می‌آید، نه از «بانک». و «بانک»، «منبع» نیست. و «منبع نبودن»، «روایت» را «یک‌طرفه» می‌کند. و «یک‌طرفه»، «اعتماد» را «کم» می‌کند.",
"@P|این «الگو»، در «پروندهٔ سامان» «برعکس» بود: بانک، «منبع» بود و «رسانه» «بازنشر» می‌کرد. و «نتیجه»، «روایت» «متوازن» بود. و «تفاوت» دو پرونده، «بودجه» نیست؛ «دسترسی» است. بانک سامان، «مدیرعامل» را «در دسترس» می‌گذاشت. ایران زمین، «در دسترس» نمی‌گذارد.",
"@P|دربارهٔ «روزنامه‌نگار»، یک «نکتهٔ حرفه‌ای» وجود دارد: «روزنامه‌نگار» «عدد» می‌خواهد و «پاسخ» می‌خواهد. اگر «عدد» بدهی و «پاسخ» بدهی، «رابطه» می‌سازی. اگر «ندهی»، «حدس» می‌زند. و «حدس»، «غلط» است. و «غلط»، «تصحیح» می‌خواهد. و «تصحیح»، «دیرتر» از «خبر» می‌رسد.",
"@P|«رابطه با روزنامه‌نگار» یک «سرمایه» است که در «صلح» ساخته می‌شود و در «بحران» «خرج» می‌شود. و ایران زمین، این «سرمایه» را «نساخته» است. چون در «صلح»، «تبلیغ» می‌کرد، نه «گفت‌وگو». و «تبلیغ»، «رابطه» نمی‌سازد؛ «آگهی» می‌سازد.",
"@P|دربارهٔ «شبکه‌های اجتماعی»، یک «تفاوت» مهم وجود دارد: در «رسانهٔ رسمی»، «خبر» «ویرایش» می‌شود. در «شبکهٔ اجتماعی»، «خبر» «بدون ویرایش» «پخش» می‌شود. و «ویرایش»، «فرصت» است. و «نبود ویرایش»، «ریسک». و بانک، در «شبکهٔ اجتماعی» «حضور» دارد اما «پاسخ» نمی‌دهد.",
"@P|یک «شاهد» وجود دارد: «همراه بانک» بانک، در «جشنوارهٔ وب و موبایل» «برندهٔ مردمی» شد (S35). یعنی «کاربر» «حضور» دارد. و «حضور»، «کانال» است. و «کانال» بدون «محتوا»، «تبلیغ» است. و «تبلیغ» در بحران، «تمسخر» می‌شود.",
"@P|این «تمسخر»، یک «ریسک واقعی» است. کاربر، «اپلیکیشن» را باز می‌کند و «خبر توقیف» را می‌بیند. و «تبلیغ» «بانکداری به سبک فردا» (S34) در «فردای بحران»، «طنز» می‌شود. و «طنز»، «اعتماد» را «نابود» می‌کند. چون «طنز»، «فاصله» بین «ادعا» و «واقعیت» را «نشان» می‌دهد.",
"@P|برداشت آرون این است که «روایت عمومی» ایران زمین، «بدون بانک» ساخته شده است. و «بدون بانک»، یعنی «بدون دفاع». و «دفاع» در بحران، «انکار» نیست؛ «توضیح» است. و «توضیح»، «حق» بانک است. و «استفاده نکردن» از این «حق»، یک «اشتباه استراتژیک» است.",
"@P|در پایان این بخش، یک «پیشنهاد» ثبت می‌شود: «میزگرد رسانه‌ای» با «سه خبرنگار تخصصی» و «یک نمایندهٔ ناظر»، در «۹۰ روز» نخست. این «میزگرد»، «رابطه» می‌سازد و «روایت» را «متوازن» می‌کند. و «هزینهٔ» آن، «کم» است. و «اثر» آن، «بلندمدت». و «نبود» آن، «هزینهٔ» آن، «همان چیزی» است که امروز «می‌بینیم».",
